CREATE TABLE IF NOT EXISTS profiles(uid TEXT PRIMARY KEY REFERENCES users(uid),bio TEXT NOT NULL DEFAULT '',pronouns TEXT NOT NULL DEFAULT '',banner TEXT NOT NULL DEFAULT '#232428');
CREATE TABLE IF NOT EXISTS game_collections(uid TEXT NOT NULL,section TEXT NOT NULL,game TEXT NOT NULL,data TEXT NOT NULL,position INTEGER NOT NULL,comment TEXT NOT NULL DEFAULT '',tags TEXT NOT NULL DEFAULT '[]',PRIMARY KEY(uid,section,game));
CREATE TABLE IF NOT EXISTS servers(id TEXT PRIMARY KEY,name TEXT NOT NULL,icon TEXT NOT NULL DEFAULT '',owner TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS server_members(server TEXT NOT NULL REFERENCES servers(id),uid TEXT NOT NULL,PRIMARY KEY(server,uid));
CREATE TABLE IF NOT EXISTS movies(id TEXT PRIMARY KEY,owner TEXT NOT NULL,data TEXT NOT NULL,object_key TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS movie_lists(uid TEXT NOT NULL,id TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(uid,id));
CREATE TABLE IF NOT EXISTS movie_progress(uid TEXT NOT NULL,id TEXT NOT NULL,position REAL NOT NULL,duration REAL NOT NULL,updated INTEGER NOT NULL,PRIMARY KEY(uid,id));
CREATE TABLE IF NOT EXISTS movie_rooms(conversation TEXT PRIMARY KEY,state TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS movie_uploads(id TEXT PRIMARY KEY,uid TEXT NOT NULL,upload_id TEXT NOT NULL,object_key TEXT NOT NULL,data TEXT NOT NULL,size INTEGER NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS expressions(id TEXT PRIMARY KEY,owner TEXT NOT NULL,kind TEXT NOT NULL,name TEXT NOT NULL,type TEXT NOT NULL,size INTEGER NOT NULL,pack TEXT,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS expression_favorites(uid TEXT NOT NULL,kind TEXT NOT NULL,id TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(uid,kind,id));
CREATE TABLE IF NOT EXISTS scheduled_messages(id TEXT PRIMARY KEY,conversation TEXT NOT NULL,sender TEXT NOT NULL,text TEXT NOT NULL,reply_to TEXT,deliver_at INTEGER NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS scheduled_messages_due ON scheduled_messages(deliver_at);

CREATE TABLE IF NOT EXISTS expression_packs(id TEXT PRIMARY KEY,name TEXT NOT NULL,shared INTEGER NOT NULL DEFAULT 0 CHECK(shared IN (0,1)));
CREATE INDEX IF NOT EXISTS expressions_pack ON expressions(pack,created DESC);
